CREATE TABLE IF NOT EXISTS underlying_assets (id SERIAL PRIMARY KEY, ticker TEXT UNIQUE NOT NULL, name TEXT NOT NULL, sector TEXT NOT NULL, exchange TEXT NOT NULL DEFAULT 'NASDAQ');
CREATE TABLE IF NOT EXISTS tokenized_assets (id SERIAL PRIMARY KEY, underlying_id INTEGER REFERENCES underlying_assets(id), provider TEXT NOT NULL, chain_id INTEGER NOT NULL DEFAULT 56, contract_address TEXT, decimals INTEGER NOT NULL DEFAULT 18, UNIQUE(underlying_id,provider));
CREATE TABLE IF NOT EXISTS market_snapshots (id BIGSERIAL PRIMARY KEY, tokenized_asset_id INTEGER REFERENCES tokenized_assets(id), token_price DOUBLE PRECISION NOT NULL, reference_price DOUBLE PRECISION NOT NULL CHECK(reference_price>0), reference_gap DOUBLE PRECISION NOT NULL, market_status TEXT NOT NULL DEFAULT 'closed', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS snapshots_asset_time ON market_snapshots(tokenized_asset_id,created_at DESC);
CREATE TABLE IF NOT EXISTS liquidity_snapshots (id BIGSERIAL PRIMARY KEY,tokenized_asset_id INTEGER REFERENCES tokenized_assets(id),trade_size DOUBLE PRECISION,quote DOUBLE PRECISION,price_impact DOUBLE PRECISION,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS radar_signals (id BIGSERIAL PRIMARY KEY,underlying_id INTEGER REFERENCES underlying_assets(id),radar_score DOUBLE PRECISION,reference_gap DOUBLE PRECISION,provider_spread DOUBLE PRECISION,z_score DOUBLE PRECISION,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS agent_policies (id UUID PRIMARY KEY,wallet_id TEXT NOT NULL DEFAULT 'demo',asset TEXT NOT NULL,conditions_json JSONB NOT NULL,action_json JSONB NOT NULL,enabled BOOLEAN NOT NULL DEFAULT false,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS trade_simulations (id UUID PRIMARY KEY,wallet_id TEXT NOT NULL DEFAULT 'demo',asset TEXT NOT NULL,input_amount DOUBLE PRECISION NOT NULL,expected_output DOUBLE PRECISION NOT NULL,slippage DOUBLE PRECISION NOT NULL,status TEXT NOT NULL,response_json JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS transactions (id UUID PRIMARY KEY,wallet_id TEXT,simulation_id UUID UNIQUE REFERENCES trade_simulations(id),tx_hash TEXT UNIQUE,chain_id INTEGER NOT NULL DEFAULT 56,status TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS api_telemetry (id BIGSERIAL PRIMARY KEY,api_module TEXT NOT NULL,endpoint TEXT NOT NULL,method TEXT NOT NULL,request_time TIMESTAMPTZ DEFAULT now(),response_time TIMESTAMPTZ DEFAULT now(),latency_ms DOUBLE PRECISION NOT NULL,status_code INTEGER NOT NULL,success BOOLEAN NOT NULL,error_code TEXT,error_message TEXT,asset TEXT,provider TEXT,request_payload JSONB,response_metadata JSONB);
